content.content:
=== ApprovalMode
export type ApprovalMode = "allowAll" | "promptUnmatched" | "onRequest" | "denyUnmatched";
=== RecoveryMode
export type RecoveryMode = "on" | "off";
=== TurnStartParams
export interface TurnStartParams {
  /** The SS3.1.1 idempotency handle (UUIDv7). The fresh turn's `turnId` derives from it (tdd SS3.1.4). */
  commandId: string;
  /** Presentation form of the prompt for transcripts. Durable; carried on the resulting user-message view item. Never model-visible (tdd SS3.2). */
  displayText?: string;
  /** Disposition when a turn is already running; default `queue`. */
  ifBusy?: IfBusy;
  /** Ordered content parts; required and non-empty. */
  input: TurnInputPart[];
  /** Reasoning tier sampled at submission for this turn. */
  reasoningEffort?: ReasoningEffort;
  /** The target session. */
  sessionId: string;
  /** A queued `!` shell action riding this turn (tdd SS3.2, ADR 50034): the `!cmd` typed while a turn runs, executed at the next model-call boundary before any later steer. Exclusive with `text` and 
  userShell?: TurnUserShell;
  /** A sticky REPLACEMENT of the session's runtime workspace-root set, binding at this turn's launch and persisting for subsequent turns until replaced again — unlike `reasoningEffort`, which is th
  workspaceRoots?: string[];
}
=== ItemDeltaParams
export interface ItemDeltaParams {
  /** The appended text; concatenation of a field path's deltas in cursor order equals that field's value on `item/completed` unless the surface saturated (spec 14653 INV-005). */
  delta: string;
  /** Dotted field path the append targets (`"summary.0"`, `"output"`, ...); absent means `"text"` (tdd SS4.3.1). */
  field?: string;
  /** The open item being appended to. */
  itemId: string;
  /** The owning session. */
  sessionId: string;
  /** Opaque, strictly monotonic view cursor (tdd SS4.1). */
  viewCursor: string;
}
=== ApprovalRequestParams
export interface ApprovalRequestParams {
  /** The approval's stable id. Match `approval/decide`, `approval/updated` and `approval/resolved` by it, never by the JSON-RPC request id, which belongs to one connection. */
  approvalId: string;
  /** The choices the server offers for the current requirement. Send the chosen one's `choiceId` in `approval/decide`; clients never build their own. */
  availableChoices: ApprovalChoice[];
  /** A Computer Use card's facts: the page, the window and each step that may have an effect, in the host's words; absent on every other approval. */
  cuaCardFacts?: ApprovalCuaCardFacts;
  /** The requirement the next decision must target; send it unchanged as `requirementId` in `approval/decide`. For `shell` it names the first stage still needing a decision; for other kinds its `sour
  currentRequirementId: ApprovalRequirementRef;
  /** The `toolCall` view item waiting on this approval. */
  itemId: string;
  /** `true` when the automated LLM judge saw this request first and handed it to a person without deciding. A display hint only. The host sends it as `false` when it re-issues the request after a res
  judgeEscalated: boolean;
  /** `true` when this approval guards a write to a protected file. Only allow-once and reject choices are offered, and a decision is accepted only while at least one client is subscribed to the sessi
  protectedWrite: boolean;
  /** The tool call's arguments as a string, usually JSON. With `toolName`, it lets a client show a subject whose `kind` it does not recognize. */
  rawArgs: string;
  /** The judge's escalation reason as one bounded display line (ADR 8609 D3: first sentence, whitespace controls folded, other control and format scalars stripped, 100 extended grapheme clusters max)
  reviewerReason?: string;
  /** The owning session. For a subagent's approval shown on the parent, this is the parent session. */
  sessionId: string;
  /** The stored records this event was folded from: an opaque token clients must not interpret. */
  sourceRange: SourceRange;
  /** Present only for a child (native subagent) approval projected onto the parent session's plane (ADR 36182); parent-own approvals omit it. */
  subagentOrigin?: ApprovalSubagentOrigin;
  /** What the approval is for. Show a `kind` you do not recognize generically, and never auto-approve it. */
  subject: ApprovalSubject;
  /** The id of the task running the tool call. */
  taskId: string;
  /** The model provider's id for this tool call. */
  toolCallId: string;
  /** The name of the tool being called. */
  toolName: string;
  /** The turn whose tool call is waiting on this approval. */
  turnId: string;
  /** The cursor of the `approval/requested` event that opened this request. A re-send for a later stage keeps this cursor, so `view/page` at it returns the opening stage, which may be older than this
  viewCursor: string;
}
=== ApprovalChoice
export interface ApprovalChoice {
  /** `true` when this choice takes optional `feedback` text in `approval/decide`, which reaches the model as guidance. Omitted when `false`. */
  acceptsFeedback?: boolean;
  /** The id to send as `choiceId` in `approval/decide`. The set of ids is open, so show `label` and do not base behavior on specific ids. */
  choiceId: string;
  /** The decision this choice applies, so a client can act on approve or reject without knowing choice ids. */
  decision: ApprovalDecision;
  /** The human-readable label to show for this choice. */
  label: string;
  /** A human-readable preview of what this choice grants, such as the policy rule it would create; show it exactly as given. */
  rulePreview?: string;
  /** The grant duration this choice declares: `once` (this request only), `session` (the rest of the session) or `localPersistent` (saved in the local policy store). */
  scope: ApprovalChoiceScope;
}
=== TurnCompletedParams
export interface TurnCompletedParams {
  /** Turn duration; absent means unmeasured, never fabricated. */
  durationMs?: number;
  /** Present when `terminal` is `"failed"`, except on a synthesized host-death terminal, which carries `reason` instead (tdd SS4.5.1, ADR 36635 D2): mid-turn failures reach the client here — never 
  error?: TurnError;
  /** The runtime's free-text terminal reason, verbatim. Display and diagnostics only; never branch on it. */
  reason?: string;
  /** The owning session. */
  sessionId: string;
  /** The durable records this event folded from. */
  sourceRange: SourceRange;
  /** The turn terminal (open enum). */
  terminal: TurnTerminal;
  /** Time to first token, when measured. */
  timeToFirstTokenMs?: number;
  /** The terminated turn. */
  turnId: string;
  /** The turn's aggregate token usage, summed across the turn's model completions (same shape as `session/tokenUsage.usage`). */
  usage?: TokenUsage;
  /** Opaque, strictly monotonic view cursor (tdd SS4.1). */
  viewCursor: string;
}
=== UserInputAnswer
export interface UserInputAnswer {
  /** A free-form answer, at most 500 characters. */
  freeText?: string;
  /** An optional comment the user adds to the answer, at most 500 characters. */
  note?: string;
  /** The `id` of the question this answers. */
  questionId: string;
  /** The label of the chosen option, for a `single` question. */
  selectedLabel?: string;
  /** The labels of the chosen options for a `multiple` question, within its selection bounds; omitted when empty. */
  selectedLabels?: string[];
}
=== UserInputRequestParams
export interface UserInputRequestParams {
  /** The auto-resolution time per question, in milliseconds: a prompt nobody engages with settles as `timedOut` after this value times the number of questions. */
  autoResolutionMs?: number;
  /** The `toolCall` view item of the tool call waiting on this prompt. */
  itemId: string;
  /** The questions to ask, one to three, in order. */
  questions: UserInputQuestion[];
  /** The session that owns the prompt. */
  sessionId: string;
  /** The stored records this prompt was folded from, when sent: an opaque token clients must not interpret. */
  sourceRange?: SourceRange;
  /** The provider's id for the tool call that opened the prompt. */
  toolCallId: string;
  /** The name of the tool that opened the prompt. */
  toolName: string;
  /** The turn whose tool call is waiting on this prompt. */
  turnId: string;
  /** The prompt's stable id. Pass it to `userInput/answer`, `userInput/cancel`, `userInput/clarify` and `userInput/interrupt`, and use it to match the later `userInput/settled`. */
  userInputId: string;
  /** The cursor of the `userInput/requested` event for this prompt. A client that missed the request can read the same payload at this cursor with `view/page`. */
  viewCursor: string;
}
=== UserInputQuestion
export interface UserInputQuestion {
  /** A short title for the question, at most 12 characters. */
  header: string;
  /** The question's id, unique within the prompt and at most 64 characters. An answer names it in `questionId`. */
  id: string;
  /** The options offered, two or three, in order. */
  options: UserInputOption[];
  /** The full question text to show the user. */
  question: string;
  /** Whether the user picks one option or several. */
  selection: UserInputSelection;
}
=== InitializeParams
export interface InitializeParams {
  /** Capability posture; absent means all defaults. */
  capabilities?: ClientCapabilities;
  /** Client identification. */
  clientInfo: ClientInfo;
}
=== SessionConfig
export interface SessionConfig {
  /** Native MCP servers added only to this session runtime. */
  mcpServers?: Record<string, SessionMcpServerConfig>;
}
=== ReasoningEffort
export type ReasoningEffort = "none" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max" | "ultra";

=== ApprovalMode
