    readonly choiceId: string;
    readonly decision: string;
    readonly label: string;
    readonly scope: string;
    readonly acceptsFeedback?: boolean;
    readonly rulePreview?: string;
  }[];
}

export interface PolicyOptions {
  readonly workspaceRoots: readonly string[];
  readonly allowWrites: boolean;
  readonly allowShell: boolean;
  readonly allowNetwork: boolean;
}

export type PolicyVerdict =
  | { readonly kind: "decide"; readonly decision: ApprovalDecisionInput; readonly why: string }
  | { readonly kind: "ask"; readonly why: string };

function within(roots: readonly string[], target: string): boolean {
  const resolved = path.resolve(target);
  return roots.some((root) => {
    const base = path.resolve(root);
    return resolved === base || resolved.startsWith(base + path.sep);
  });
}

function choose(
  request: ApprovalRequestView,
  decisions: readonly string[],
  scope: string | undefined,
): ApprovalRequestView["availableChoices"][number] | undefined {
  return request.availableChoices.find(
    (c) => decisions.includes(c.decision) && (scope === undefined || c.scope === scope),
  );
}

export function approve(request: ApprovalRequestView, why: string): PolicyVerdict {
  const choice = choose(request, ["approved"], "once");
  if (choice === undefined) return { kind: "ask", why: `${why}; no allow-once choice offered` };
  return { kind: "decide", decision: { choiceId: choice.choiceId }, why };
}

export function deny(request: ApprovalRequestView, why: string): PolicyVerdict {
  const choice = choose(request, ["denied", "abort"], undefined);
  if (choice === undefined) return { kind: "ask", why: `${why}; no reject choice offered` };
  const decision: ApprovalDecisionInput =
    choice.acceptsFeedback === true
      ? { choiceId: choice.choiceId, feedback: `Denied by harness policy: ${why}.` }
      : { choiceId: choice.choiceId };
  return { kind: "decide", decision, why };
}

export function evaluate(request: ApprovalRequestView, opts: PolicyOptions): PolicyVerdict {
  const s = request.subject;
  switch (s.kind) {
    case "fileAccess": {
      if (s.path === undefined) return { kind: "ask", why: "file access without a path" };
      const inside = within(opts.workspaceRoots, s.path);
      if (s.access === "read") {
        return inside ? approve(request, `read inside workspace: ${s.path}`) : { kind: "ask", why: `read outside workspace: ${s.path}` };
      }
      if (s.access === "write") {
        if (!inside) return deny(request, `write outside workspace roots (${s.path})`);
        if (request.protectedWrite) return { kind: "ask", why: `protected file write: ${s.path}` };
        return opts.allowWrites ? approve(request, `write inside workspace: ${s.path}`) : { kind: "ask", why: `write: ${s.path}` };
      }
      return { kind: "ask", why: `file access '${s.access ?? "?"}': ${s.path}` };
    }
    case "shell":
      return opts.allowShell ? approve(request, `shell: ${s.command ?? request.rawArgs}`) : { kind: "ask", why: `shell: ${s.command ?? request.rawArgs}` };
    case "network": {
      const target = `${s.host ?? "?"}${s.port !== undefined ? `:${s.port}` : ""}`;
      return opts.allowNetwork ? approve(request, `network: ${target}`) : { kind: "ask", why: `network: ${target}` };
    }
    default:
      // Unknown kinds are shown and decided by a person, never auto-approved.
      return { kind: "ask", why: `${s.kind}: ${request.toolName}` };
  }
}

