};

const dim = (s: string) => (process.stderr.isTTY ? `\x1b[2m${s}\x1b[0m` : s);
const note = (s: string) => process.stderr.write(dim(s) + "\n");

// One readline for prompts, approvals and questions; calls are serialized.
let rl: Interface | undefined;
let rlQueue: Promise<unknown> = Promise.resolve();
function ask(question: string): Promise<string> {
  rl ??= createInterface({ input: process.stdin, output: process.stderr });
  const r = rl;
  const next = rlQueue.then(() => r.question(question));
  rlQueue = next.catch(() => undefined);
  return next;
}

// ---- transcript ---------------------------------------------------------
const runsDir = path.join(import.meta.dirname, "..", "runs");
async function record(sessionId: string, entry: Record<string, unknown>): Promise<void> {
  await mkdir(runsDir, { recursive: true });
  await appendFile(path.join(runsDir, `${sessionId}.jsonl`), JSON.stringify({ at: new Date().toISOString(), ...entry }) + "\n");
}

// ---- approvals ----------------------------------------------------------
async function onApproval(request: ApprovalRequestView) {
  const verdict = evaluate(request, policy);
  if (verdict.kind === "decide") {
    note(`  ✓ policy: ${verdict.why} → ${request.availableChoices.find((c) => c.choiceId === verdict.decision.choiceId)?.label}`);
    return verdict.decision;
  }
  if (!interactive) {
    const d = deny(request, `no operator attached (${verdict.why})`);
    if (d.kind === "decide") {
      note(`  ✗ policy: ${d.why}`);
      return d.decision;
    }
    throw new Error(`approval needs a person and none is attached: ${verdict.why}`);
  }
  const lines = [
    `\n⚠ approval: ${request.toolName} — ${verdict.why}`,
    request.judgeEscalated ? `  judge escalated${request.reviewerReason ? `: ${request.reviewerReason}` : ""}` : "",
    request.protectedWrite ? "  protected file: only allow-once or reject" : "",
    ...request.availableChoices.map(
      (c, i) => `  [${i + 1}] ${c.label} (${c.scope})${c.rulePreview ? ` — ${c.rulePreview}` : ""}`,
    ),
  ].filter(Boolean);
  process.stderr.write(lines.join("\n") + "\n");
  for (;;) {
    const answer = (await ask("choice> ")).trim();
    const choice = request.availableChoices[Number(answer) - 1];
    if (choice === undefined) continue;
    if (choice.acceptsFeedback === true) {
      const feedback = (await ask("feedback for the model (enter to skip)> ")).trim();
      if (feedback !== "") return { choiceId: choice.choiceId, feedback };
    }
    return { choiceId: choice.choiceId };
  }
}

// ---- agent questions ----------------------------------------------------
const answered = new Set<string>();
async function answerQuestions(session: Session): Promise<void> {
  for (const pending of session.fold.pendingUserInputs()) {
    if (answered.has(pending.userInputId)) continue;
    answered.add(pending.userInputId);
    const answers = [];
    for (const q of pending.questions) {
      process.stderr.write(`\n? [${q.header}] ${q.question}\n`);
      q.options.forEach((o, i) => process.stderr.write(`  [${i + 1}] ${o.label}${o.description ? ` — ${o.description}` : ""}\n`));
      const multiple = q.selection.mode === "multiple";
      const raw = (await ask(multiple ? "numbers (comma-separated) or text> " : "number or text> ")).trim();
      const picks = raw.split(",").map((p) => q.options[Number(p.trim()) - 1]?.label);
      if (picks.every((p) => p !== undefined) && picks.length > 0) {
        answers.push(multiple ? { questionId: q.id, selectedLabels: picks as string[] } : { questionId: q.id, selectedLabel: picks[0] as string });
      } else {
        answers.push({ questionId: q.id, freeText: raw.slice(0, 500) });
      }
    }
    const result = await session.answerUserInput(pending.userInputId, answers);
    note(`  answered ${pending.userInputId}: ${JSON.stringify(result)}`);
  }
}

// ---- turns --------------------------------------------------------------
async function buildInput(text: string, images: readonly string[], skills: readonly string[]) {
  const parts: { type: "text" | "image" | "skill"; text?: string; base64Data?: string; mediaType?: string; selector?: string }[] = [];
  for (const s of skills) parts.push({ type: "skill", selector: s });
  for (const file of images) {
    const mediaType = IMAGE_TYPES[path.extname(file).toLowerCase()];
    if (mediaType === undefined) throw new Error(`unsupported image type: ${file}`);
    parts.push({ type: "image", mediaType, base64Data: (await readFile(file)).toString("base64") });
  }
  if (text !== "") parts.push({ type: "text", text });
  return parts;
}

async function runTurn(
  session: Session,
  input: Awaited<ReturnType<typeof buildInput>>,
  extra: { displayText?: string; userShell?: { commandText: string } } = {},
): Promise<boolean> {
  const turn = await session.sendUserTurn({
    input,
    ifBusy: "queue",
    ...(effort !== undefined ? { reasoningEffort: effort } : {}),
    ...extra,
  });
  const kinds = new Map<string, string>();
  const seen = new Set<string>();
  let streamedText = false;

  const items = (async () => {
    for await (const item of turn.items()) {
      kinds.set(item.itemId, item.kind);
      const key = `${item.itemId}:${item.status}`;
      if (seen.has(key)) continue;
      seen.add(key);
      if (opt.json) process.stdout.write(JSON.stringify(item) + "\n");
      if (item.status !== "inProgress") await record(session.sessionId, { type: "item", item });
      describe(item);
      await answerQuestions(session);
    }
  })();

  const deltas = (async () => {
    for await (const d of turn.deltas()) {
      const kind = kinds.get(d.itemId);
      if (kind === "reasoning") {
        if (opt["show-reasoning"]) process.stderr.write(dim(d.delta));
      } else if ((d.field === undefined || d.field === "text") && (kind === undefined || kind === "agentMessage") && !opt.json) {
        process.stdout.write(d.delta);
        streamedText = true;
      }
    }
  })();

  // Questions can arrive while no item moves; check the fold until the turn settles.
  const ticker = setInterval(() => void answerQuestions(session).catch((e) => note(`question error: ${String(e)}`)), 300);
  try {
    const outcome = await turn.completed;
    await Promise.allSettled([items, deltas]);
    if (streamedText) process.stdout.write("\n");
    await record(session.sessionId, { type: "outcome", outcome });
    if (outcome.kind === "completed") {
      const p = outcome.params;
      const u = p.usage;
      note(
        `— ${p.terminal}` +
          (p.durationMs !== undefined ? ` in ${(p.durationMs / 1000).toFixed(1)}s` : "") +
          (p.timeToFirstTokenMs !== undefined ? `, ttft ${p.timeToFirstTokenMs}ms` : "") +
          (u ? `, tokens in ${u.inputTokens} (cached ${u.cachedTokens}) out ${u.outputTokens}` : ""),
      );
      if (p.error) note(`  error ${p.error.kind}: ${p.error.message}`);
      if (isLaunchFailure(outcome)) note("  the turn never launched");
      return p.terminal === "completed";
    }
    note(`— ${outcome.kind}`);
    return false;
  } finally {
    clearInterval(ticker);
  }
}

function describe(item: FoldedItem): void {
  if (opt.json || item.status === "inProgress") return;
  switch (item.kind) {
    case "toolCall":
      note(`  ▸ ${item.tool ?? "tool"} ${item.status}${item.displayLabel ? ` ${JSON.stringify(item.displayLabel)}` : ""}`);
      break;
    case "userShell":
      note(`  $ ${item.commandText ?? ""} → exit ${item.exitCode ?? "?"}`);
      if (item.visibleOutput) process.stdout.write(item.visibleOutput + "\n");
      break;
    case "subagent":
    case "workflow":
      note(`  ⇢ ${item.kind} ${item.label ?? item.objective ?? ""} ${item.status}`);
      break;
    case "compaction":
      note(`  ⟲ context compacted (${item.tokensBefore ?? "?"} → ${item.tokensAfter ?? "?"} tokens)`);
      break;
    case "webSearch":
      note(`  ⌕ web search ${item.status}`);
      break;
    case "agentMessage":
    case "reasoning":
    case "userMessage":
      break;
    default:
      note(`  · ${item.kind} ${item.status}`);
  }
}

function printState(session: Session): void {
  const state = session.fold.sessionState;
  for (const family of state.families()) {
    console.log(`${family}: ${JSON.stringify(state.get(family as SessionStateMethod))}`);
  }
}

// ---- main ---------------------------------------------------------------
async function main(): Promise<number> {
  const args = ["serve"];
  if (opt.provider) args.push("--provider", opt.provider);
  if (opt.model) args.push("--model", opt.model);
  if (opt.ephemeral) args.push("--no-session-log");

  let client: MuseClient;
  try {
    client = await MuseClient.spawn({
      museBin: opt["muse-bin"],
      args,
      cwd: roots[0],
      env: process.env,
      clientInfo: { name: "etched-muse", version: "0.1.0" },
      capabilities: {
        // MCP is intentionally not requested: this project acts only through 3tchedFS.
        requestedCapabilities: ["userShell", "feedback", "sessionRename", "sessionListStream"],
        userInputDialogs: interactive,
      },
      onStderr: (chunk) => {
        if (process.env.MUSE_DEBUG) process.stderr.write(dim(chunk));
      },
    });
  } catch (e) {
    if (e instanceof MuseHostStartError) {
      console.error(`muse serve failed to start: ${e.message}`);
      return 1;
    }
    throw e;
  }

  const init = client.initializeResult;
  const fp = checkServedFingerprint(init.schema.fingerprint);
  note(
    `muse ${init.serverInfo.version} · ${client.durability.kind} sessions · sandbox ${init.sandboxAvailability ?? "unknown"} · granted [${init.grantedCapabilities.join(", ")}]`,
  );
  if (fp) note(`⚠ ${fp.message}`);
  void client.exit.then((exit) => {
    if (exit.kind !== "cleanShutdown") note(`muse host exited: ${exit.kind}${"stderrTail" in exit ? `\n${exit.stderrTail.join("\n")}` : ""}`);
  });

  const onApprovalError = (f: { kind: string; approvalId: string }) => note(`approval ${f.approvalId} failed: ${f.kind}`);
  let session: Session;
  if (opt.resume) {
    session = await client.resumeSession({
      sessionId: opt.resume,
      onApproval: (r) => onApproval(r as unknown as ApprovalRequestView),
      onApprovalError,
    });
  } else {
    session = await client.startSession({
      workspaceRoot: roots[0],
      workspaceRoots: roots,
      recoveryMode: "on",
      ...(opt.model ? { modelId: opt.model } : {}),
      ...(opt.provider ? { providerId: opt.provider } : {}),
      ...(approvalMode ? { approvalMode } : {}),
      ...(opt["permission-profile"] ? { permissionProfile: opt["permission-profile"], requirePermissionProfile: true } : {}),
    });
    session.onApproval((r) => onApproval(r as unknown as ApprovalRequestView));
    session.onApprovalError(onApprovalError);
  }
  session.onGapError((f) => note(`event gap could not be filled: ${JSON.stringify(f)}`));
  note(`session ${session.sessionId}${opt.resume ? " (resumed)" : ""} · roots ${roots.join(", ")}`);
  await record(session.sessionId, { type: "open", resumed: Boolean(opt.resume), roots, provider: opt.provider, model: opt.model });

  const shutdown = async (code: number) => {
    rl?.close();
    await client.close();
    return code;
  };
  process.once("SIGINT", () => void shutdown(130).then((c) => process.exit(c)));

  try {
    if (!repl) {
      const text = prompt !== "" ? prompt : (await readStdin()).trim();
      if (text === "") {
        console.error(HELP);
        return shutdown(2);
      }
      const ok = await runTurn(session, await buildInput(text, opt.image ?? [], opt.skill ?? []));
      return shutdown(ok ? 0 : 1);
    }

    note("REPL — /help for commands, /quit to exit");
    let images = [...(opt.image ?? [])];
    for (;;) {
      const line = (await ask("muse> ")).trim();
      if (line === "") continue;
      if (line.startsWith("!")) {
        await runTurn(session, [], { userShell: { commandText: line.slice(1) }, displayText: line });
        continue;
      }
      if (line.startsWith("/")) {
        const [cmd, ...rest] = line.slice(1).split(/\s+/);
        const arg = rest.join(" ");
        if (cmd === "quit" || cmd === "exit") break;
        else if (cmd === "help")
          note("/effort <e> · /image <path> · /skill <name> [text] · /state · /turns · /session · /quit · !<shell cmd>");
        else if (cmd === "effort") effort = oneOf("effort", arg, EFFORTS);
        else if (cmd === "image") images.push(arg);
        else if (cmd === "skill") await runTurn(session, await buildInput(rest.slice(1).join(" "), [], [rest[0] ?? ""]));
        else if (cmd === "state") printState(session);
        else if (cmd === "turns") for (const t of session.fold.turns()) console.log(JSON.stringify(t));
        else if (cmd === "session") console.log(`${session.sessionId}  (resume: npm run muse -- --resume ${session.sessionId})`);
        else note(`unknown command /${cmd}`);
        continue;
      }
      await runTurn(session, await buildInput(line, images, []));
      images = [];
    }
    note(`resume later: npm run muse -- --resume ${session.sessionId}`);
    return shutdown(0);
  } catch (e) {
    if (e instanceof MuseHostDiedError) {
      console.error(`muse host died: ${e.exit.kind}`);
      return 1;
    }
    await shutdown(1);
    throw e;
  }
}

async function readStdin(): Promise<string> {
  if (process.stdin.isTTY) return "";
  const chunks: Buffer[] = [];
  for await (const c of process.stdin) chunks.push(c as Buffer);
  return Buffer.concat(chunks).toString("utf8");
}

process.exitCode = await main();

