  // jev_verify — claim vs evidence (cookbooks/citation_check)
  // -------------------------------------------------------------------
  pi.registerTool({
    name: "jev_verify",
    label: "Jev Verify",
    description:
      "Verify a claim against its cited evidence in one TypeSafe request: a Choice picks whether the source supports the claim (supports / contradicts / insufficient), a Noul checks whether the quote appears verbatim, and a Score rates how misleading it would be to keep the claim. Confidence flags uncertain verdicts for human review. Use to double-check citations, hallucinated quotes, and fact-grounding.",
    parameters: z.object({
      claim: z.string().describe("The claim or statement being made."),
      evidence: z.string().describe("The source text it cites (document excerpt, search result, file content)."),
      quote: z.string().optional().describe("Optional verbatim quote claimed to come from the evidence."),
      model: z.string().optional().describe(`TypeSafe model (default ${DEFAULT_MODEL}).`),
    }),
    async execute(_id, params, signal) {
      const state = { claim: params.claim, evidence: params.evidence, quote: params.quote ?? null };
      const questions: Record<string, Question> = {
