// omp extension: lets omp delegate work to the Muse Code agent over MSP.
//
// Registers the `muse_code` tool and the `/muse` command. One `muse serve`
// host is spawned lazily and reused; sessions persist, so omp can continue
// one with `session_id`. Approvals go through the shared client policy
// (policy.ts); anything it cannot decide is put to the person in omp's UI,
// or denied when no UI is attached. Loaded from
// `hackathon/.omp/extensions/muse-code/` so imports resolve here.

import path from "node:path";
import { MuseClient, checkServedFingerprint, type Session } from "@muse-code/sdk";
import { deny, evaluate, type ApprovalRequestView } from "./policy.ts";

// The subset of omp's ExtensionAPI this file uses (its types are not installed here).
interface Ui {
  notify(message: string, level?: "info" | "warning" | "error"): void;
  select?(title: string, options: string[]): Promise<string | undefined>;
  input?(title: string, placeholder?: string): Promise<string | undefined>;
  setStatus?(key: string, text: string | undefined): void;
}
interface Ctx { readonly ui: Ui; readonly hasUI?: boolean; readonly cwd?: string }
type ToolResult = { content: { type: "text"; text: string }[]; details?: unknown };
interface Api {
  readonly zod: typeof import("zod");
  setLabel(label: string): void;
  on(event: string, handler: (event: unknown, ctx: Ctx) => unknown): void;
  registerTool(tool: {
    name: string;
    label: string;
    description: string;
    parameters: unknown;
    execute(
      id: string,
      params: Params,
      signal?: AbortSignal,
      onUpdate?: (partial: ToolResult) => void,
      ctx?: Ctx,
    ): Promise<ToolResult>;
  }): void;
  registerCommand(name: string, cmd: { description: string; handler(args: string, ctx: Ctx): Promise<void> }): void;
  sendMessage(msg: { customType: string; content: string; display: boolean }, opts?: { triggerTurn?: boolean }): void;
}
interface Params {
  task: string;
  session_id?: string;
  effort?: "none" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max" | "ultra";
  allow_writes?: boolean;
  allow_shell?: boolean;
}

const HACKATHON = path.resolve(import.meta.dirname, "..", "..");

export default function museCode(pi: Api) {
  const z = pi.zod;
  pi.setLabel("Muse Code");

  let client: Promise<MuseClient> | undefined;
  const sessions = new Map<string, Session>();
  let uiCtx: Ctx | undefined;
  let allow = { writes: false, shell: false };

  function host(): Promise<MuseClient> {
    client ??= MuseClient.spawn({
      museBin: process.env.MUSE_BIN ?? "muse",
      args: ["serve", ...(process.env.MUSE_MODEL ? ["--model", process.env.MUSE_MODEL] : [])],
      cwd: HACKATHON,
      env: process.env,
      clientInfo: { name: "etched_omp", version: "0.1.0" },
      // No MCP: this project acts only through 3tchedFS.
      capabilities: { requestedCapabilities: ["feedback", "sessionRename"], userInputDialogs: true },
    }).then((c) => {
      const fp = checkServedFingerprint(c.initializeResult.schema.fingerprint);
      if (fp) uiCtx?.ui.notify(fp.message, "warning");
      void c.exit.then((exit) => {
        client = undefined;
        sessions.clear();
        if (exit.kind !== "cleanShutdown") uiCtx?.ui.notify(`muse host exited: ${exit.kind}`, "error");
      });
      return c;
    }, (e: unknown) => {
      client = undefined;
      throw e;
    });
    return client;
  }

  async function onApproval(raw: unknown) {
    const request = raw as ApprovalRequestView;
    const verdict = evaluate(request, {
      workspaceRoots: [HACKATHON],
      allowWrites: allow.writes,
      allowShell: allow.shell,
      allowNetwork: false,
    });
    if (verdict.kind === "decide") return verdict.decision;
    const ui = uiCtx?.ui;
    if (uiCtx?.hasUI !== false && ui?.select) {
      const labels = request.availableChoices.map((c) => `${c.label} (${c.scope})${c.rulePreview ? ` — ${c.rulePreview}` : ""}`);
      const picked = await ui.select(`Muse wants ${request.toolName}: ${verdict.why}`, labels);
      const choice = request.availableChoices[picked === undefined ? -1 : labels.indexOf(picked)];
      if (choice) {
        const feedback = choice.acceptsFeedback && ui.input ? await ui.input("Feedback for Muse (optional)") : undefined;
        return feedback ? { choiceId: choice.choiceId, feedback } : { choiceId: choice.choiceId };
      }
    }
    const d = deny(request, `no decision from omp (${verdict.why})`);
    if (d.kind === "decide") return d.decision;
    throw new Error(`approval could not be decided: ${verdict.why}`);
  }

  async function answerQuestions(session: Session, asked: Set<string>) {
    const ui = uiCtx?.ui;
    for (const p of session.fold.pendingUserInputs()) {
      if (asked.has(p.userInputId)) continue;
      asked.add(p.userInputId);
      const answers = [];
      for (const q of p.questions) {
        const labels = q.options.map((o) => o.label);
        const pick = ui?.select ? await ui.select(`Muse asks: ${q.question}`, [...labels, "Other…"]) : undefined;
        if (pick !== undefined && pick !== "Other…") {
          answers.push(q.selection.mode === "multiple" ? { questionId: q.id, selectedLabels: [pick] } : { questionId: q.id, selectedLabel: pick });
        } else {
          const text = (ui?.input ? await ui.input(q.question) : undefined) ?? "No answer available; use your best judgment.";
          answers.push({ questionId: q.id, freeText: text.slice(0, 500) });
        }
      }
      await session.answerUserInput(p.userInputId, answers);
    }
  }

  async function open(sessionId: string | undefined): Promise<Session> {
    const c = await host();
    if (sessionId) {
      const known = sessions.get(sessionId);
      if (known) return known;
      const s = await c.resumeSession({ sessionId, onApproval, onApprovalError: (f) => uiCtx?.ui.notify(`approval ${f.kind}`, "warning") });
      sessions.set(s.sessionId, s);
      return s;
    }
    const s = await c.startSession({ workspaceRoot: HACKATHON, recoveryMode: "on" });
    s.onApproval(onApproval);
    s.onApprovalError((f) => uiCtx?.ui.notify(`approval ${f.kind}`, "warning"));
    sessions.set(s.sessionId, s);
    return s;
  }

  async function run(params: Params, signal?: AbortSignal, onUpdate?: (r: ToolResult) => void): Promise<ToolResult> {
    allow = { writes: params.allow_writes === true, shell: params.allow_shell === true };
    const session = await open(params.session_id);
    const turn = await session.sendUserTurn({
      input: [{ type: "text", text: params.task }],
      ifBusy: "queue",
      ...(params.effort ? { reasoningEffort: params.effort } : {}),
    });
    const tools: string[] = [];
    const finalText = new Map<string, string>();
    let live = "";
    const asked = new Set<string>();
    const ticker = setInterval(() => void answerQuestions(session, asked).catch(() => undefined), 300);
    const onAbort = () => void client?.then((c) => c.close());
    signal?.addEventListener("abort", onAbort, { once: true });
    const update = () => onUpdate?.({ content: [{ type: "text", text: [...tools.slice(-5), live.slice(-1500)].join("\n") }] });

    const items = (async () => {
      for await (const item of turn.items()) {
        if (item.kind === "agentMessage" && item.text) finalText.set(item.itemId, item.text);
        if (item.kind === "toolCall" && item.status !== "inProgress") {
          tools.push(`▸ ${item.tool ?? "tool"} ${item.status}`);
          update();
        }
      }
    })();
    const deltas = (async () => {
      for await (const d of turn.deltas()) {
        if (d.field === undefined || d.field === "text") {
          live += d.delta;
          update();
        }
      }
    })();

    try {
      const outcome = await turn.completed;
      await Promise.allSettled([items, deltas]);
      const text = [...finalText.values()].join("\n\n") || live;
      const p = outcome.kind === "completed" ? outcome.params : undefined;
      const footer = [
        `muse session ${session.sessionId} (pass as session_id to continue)`,
        `terminal: ${p?.terminal ?? outcome.kind}${p?.error ? ` — ${p.error.kind}: ${p.error.message}` : ""}`,
        p?.usage ? `tokens in ${p.usage.inputTokens} out ${p.usage.outputTokens}` : "",
        tools.length ? `tools: ${tools.length}` : "",
      ].filter(Boolean).join("\n");
      return {
        content: [{ type: "text", text: `${text}\n\n---\n${footer}` }],
        details: { sessionId: session.sessionId, outcome, tools },
      };
    } finally {
      clearInterval(ticker);
      signal?.removeEventListener("abort", onAbort);
    }
  }

  pi.on("session_start", async (_e, ctx) => {
    uiCtx = ctx;
  });
  for (const ev of ["session_shutdown", "shutdown"]) {
    try {
      pi.on(ev, async () => {
        await client?.then((c) => c.close()).catch(() => undefined);
      });
    } catch {
      /* event not supported by this omp version */
    }
  }

  pi.registerTool({
    name: "muse_code",
    label: "Muse Code",
    description:
      "Delegate a coding or research task in the hackathon workspace to Meta's Muse Code agent (Muse Spark), which runs its own tools (read, search, edit, shell) under the harness approval policy. Reads inside hackathon/ are allowed; writes and shell need allow_writes / allow_shell or a person's approval; anything outside the workspace is denied. Returns Muse's final answer and a session_id to continue the same Muse session. Use for self-contained subtasks, second opinions, or work that should be attributed to Muse.",
    parameters: z.object({
      task: z.string().describe("What Muse should do, with all needed context; Muse does not see this conversation."),
      session_id: z.string().optional().describe("Continue an earlier Muse session (from a previous result)."),
      effort: z.enum(["none", "minimal", "low", "medium", "high", "xhigh", "max", "ultra"]).optional().describe("Muse reasoning effort for this turn."),
      allow_writes: z.boolean().optional().describe("Approve Muse's file writes inside hackathon/ without asking."),
      allow_shell: z.boolean().optional().describe("Approve Muse's shell commands without asking."),
    }),
    async execute(_id, params, signal, onUpdate, ctx) {
      if (ctx) uiCtx = ctx;
      return run(params, signal, onUpdate);
    },
  });

  pi.registerCommand("muse", {
    description: "Ask Muse Code directly: /muse <task>",
    handler: async (args, ctx) => {
      uiCtx = ctx;
      if (!args.trim()) {
        ctx.ui.notify("usage: /muse <task>", "info");
        return;
      }
      ctx.ui.setStatus?.("muse", "muse working…");
      try {
        const r = await run({ task: args.trim() });
        pi.sendMessage({ customType: "muse-code", content: r.content[0]?.text ?? "", display: true }, { triggerTurn: false });
      } catch (e) {
        ctx.ui.notify(`muse failed: ${String(e)}`, "error");
      } finally {
        ctx.ui.setStatus?.("muse", undefined);
      }
    },
  });
}

