function outPath(c: Conv): string {
  const id = createHash("sha1").update(c.source).digest("hex").slice(0, 10);
  return join(SESS, c.tool, `${c.date || "unknown"}__${id}.md`);
}

function write(c: Conv) {
  if (!c.lines.some((l) => l.tag !== "A")) return; // no human turns: nothing to judge against
  const p = outPath(c);
  mkdirSync(dirname(p), { recursive: true, mode: 0o700 });
  writeFileSync(p + ".tmp", render(c), { mode: 0o600 });
  renameSync(p + ".tmp", p);
}

async function eachLine(file: string, fn: (line: string) => void) {
  const rl = createInterface({ input: createReadStream(file, { encoding: "utf8" }), crlfDelay: Infinity });
  for await (const line of rl) fn(line);
}
function parse(line: string): any {
  if (!line || line[0] !== "{") return null;
  try { return JSON.parse(line); } catch { return null; }
}

function walk(dir: string, out: string[] = []): string[] {
  let names: string[] = [];
  try { names = readdirSync(dir); } catch { return out; }
  for (const n of names) {
    const p = join(dir, n);
    let st; try { st = statSync(p); } catch { continue; }
    if (st.isDirectory()) walk(p, out);
    else if (n.endsWith(".jsonl")) out.push(p);
  }
  return out;
}

const toolFromPath = (p: string) =>
  Object.entries(LIVE).find(([, d]) => p.startsWith(d + "/"))?.[0] ??
  (p.includes("/.hermes/") ? "hermes" : p.includes("/.gemini/") ? "gemini" : p.includes("/.cursor/") ? "cursor" : "other");

async function main() {
  mkdirSync(SESS, { recursive: true, mode: 0o700 });
  const state: Record<string, string> = !full && existsSync(STATE) ? JSON.parse(readFileSync(STATE, "utf8")) : {};
  const next: Record<string, string> = {};
  let changed = 0, convs = 0;
  const t0 = Date.now();

  // Source = the collected conversation folder only (gathered by the NotebookLM
  // collection agent, which already extracts SQLite stores). Out-of-scope gaps are
  // fixed in that collector, not here.
  const live = new Set<string>();
  // Capture chunks.
  if (existsSync(CHUNKS)) {
    for (const n of readdirSync(CHUNKS)) {
      if (!n.endsWith(".txt")) continue;
      const f = join(CHUNKS, n);
      const sig = n.split("__").pop()!.replace(/\.txt$/, ""); // filename carries the sha prefix
      next[f] = sig;
      if (state[f] === sig) continue;
      changed++;
      let x: Extract | null = null;
      await eachLine(f, (l) => {
        if (l.startsWith("SOURCE ")) {
          if (x) { write(x.done()); convs++; }
          const src = l.slice(7).split(" | ")[0].trim();
          x = src.endsWith(".jsonl") ? new Extract(toolFromPath(src), src) : null;
          return;
        }
        if (x) { const r = parse(l); if (r) x.record(r); }
      });
      if (x) { write((x as Extract).done()); convs++; }
    }
  }

  writeFileSync(STATE + ".tmp", JSON.stringify(next), { mode: 0o600 });
  renameSync(STATE + ".tmp", STATE);
  const secs = ((Date.now() - t0) / 1000).toFixed(1);

  // 3) Pack the ledger with repomix: line-numbered JSON (for Jev/models) and an
  //    XML backfill bundle for NotebookLM — every model's conversations in one
  //    notebook, split into parts that stay well under NotebookLM's per-source size.
