/**
 * Jev judge — typed decisions over a state, via TypeSafe System One.
 *
 * Two uses:
 *  - judge(state, questions): generic; exposed as the MCP tool `jev_judge`.
 *  - judgeTurn(prompt): the fixed per-turn decision set. Hosts call it BEFORE
 *    the model starts (OMP before_agent_start, Hermes proxy) and hand the
 *    result to the model as a short note — so the decision is forced every
 *    turn instead of depending on the model choosing to call a tool.
 *
 * Fail-open: any error returns null and the turn proceeds unchanged.
 */
import { execFile } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { promisify } from "node:util";

const exec = promisify(execFile);
const ENDPOINT = process.env.TYPESAFE_ENDPOINT || "https://api.typesafe.ai/v1/systemone";
const MODEL = process.env.TYPESAFE_MODEL || "jev-latest";

export type Question =
  | { type: "noul"; instructions: string; criteria?: { true?: string; false?: string } }
  | { type: "choice"; instructions: string; criteria: Record<string, string> }
  | { type: "score"; instructions: string; criteria: string[] };

async function key(): Promise<string | null> {
  if (process.env.TYPESAFE_API_KEY) return process.env.TYPESAFE_API_KEY;
  try {
    const { stdout } = await exec("omp", ["token", "typesafe"], { timeout: 5000 });
    return stdout.trim() || null;
  } catch {
    return null;
  }
}

/** One batched Jev call. Returns the raw `answers` map, or null on any failure. */
  }
}

/** The fixed per-turn decision set (edit here to change what is asked every turn). */
export const TURN_QUESTIONS: Record<string, Question> = {
  intent: {
    type: "choice",
    instructions: "What is the user asking for in this message?",
    criteria: {
      question: "An explanation, answer or opinion; nothing should be changed.",
      change: "Edit code, files, configuration or systems.",
      investigate: "Diagnose or look into something before deciding what to change.",
    },
  },
  plan_first: {
    type: "noul",
    instructions: "Does this need a short plan before acting (multi-step, multi-file, or ambiguous)?",
  },
  risky: {
    type: "noul",
    instructions: "Could carrying this out be destructive or hard to undo (deleting data, production, security, credentials, force pushes)?",
  },
  search_needed: {
    type: "noul",
    instructions: "Will this need searching or reading across the codebase or logs to answer well?",
  },
  relevant: {
    type: "noul",
    instructions: "Is the new message relevant to the task the current conversation (history) is working on? If there is no history, answer true.",
  },
  deprecated: {
    type: "noul",
    instructions: "Does the new message rely on something the history or past_conversations show is deprecated, retired, superseded or removed?",
  },
  already_decided: {
    type: "noul",
    instructions: "Has the history or past_conversations already decided or answered what the new message asks for?",
  },
  repeat: {
