//! `jev` method contracts: content judgments, never routing.
//!
//! `decide` asks Jev (TypeSafe System One) a fixed set of typed questions
//! about one piece of recorded chat content: a request before the model
//! answers it, or the chatbot's own reply after it. The caller supplies the
//! reference passages (the identity's own recorded, vectorized history), so
//! this plugin reads no store and holds no state. A judgment is advisory: it
//! never blocks, reroutes or edits content.
//!
//! A reply judgment can raise a `learning_event` — an introspective record
//! the chatbot retrieves first on later turns. Raising one is a pure rule
//! over the judgment ([`classify_learning_event`]); promoting a lesson to a
//! standing rule is an owner decision outside this plugin.
//!
//! The credential comes only from the environment, is sent only to the
//! pinned HTTPS origin, and never appears in output, state or schema.

use std::time::Duration;

use anyhow::{Context, Result, ensure};
use reqwest::Client;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

/// The one TypeSafe endpoint this plugin may send content and its key to.
pub const JEV_ENDPOINT: &str = "https://api.typesafe.ai/v1/systemone";
const DEFAULT_MODEL: &str = "jev-latest";
const KEY_VARS: [&str; 2] = ["JEV_TYPESAFE_API_KEY", "TYPESAFE_API_KEY"];

const MAX_SUBJECT_BYTES: usize = 8_000;
const MAX_CONTEXT_BYTES: usize = 6_000;
const MAX_PASSAGES: usize = 8;
const MAX_PASSAGE_BYTES: usize = 1_500;
const MAX_SOURCE_BYTES: usize = 256;

/// Probability at or above which a yes/no judgment counts as raised.
pub const RAISED: f64 = 0.7;
/// Score (0..=3) below which a fit judgment counts as weak.
pub const WEAK: f64 = 1.5;

#[derive(Debug, Clone, Copy, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum SubjectKind {
    /// A human request, judged before the model answers it.
    Request,
    /// The chatbot's own reply, judged after the turn (may raise a learning event).
    Reply,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Passage {
    /// Where the passage came from (record id, conversation, date); cited back.
    pub source: String,
    pub text: String,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct DecideContext {
    /// The architecture rules the content should fit.
    #[serde(default)]
    pub architecture: Option<String>,
    /// Who the content is for.
    #[serde(default)]
    pub audience: Option<String>,
    /// What earns attention (e.g. judging priorities), most important first.
    #[serde(default)]
    pub priorities: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct DecideInput {
    /// The content judged: a request, or the chatbot's reply.
    pub subject: String,
    pub kind: SubjectKind,
    /// For a reply: the request it answered.
    #[serde(default)]
    pub request: Option<String>,
    /// For a reply: the human corrected, redirected or interrupted the turn
    /// (e.g. episode outcome `direction_changed` / `interrupted`).
    #[serde(default)]
    pub user_corrected: bool,
    /// Reference passages from the identity's own recorded history.
    #[serde(default)]
    pub passages: Vec<Passage>,
    #[serde(default)]
    pub context: DecideContext,
}

impl DecideInput {
    pub fn validate(&self) -> Result<()> {
        ensure!(!self.subject.trim().is_empty(), "subject must not be empty");
        ensure!(self.subject.len() <= MAX_SUBJECT_BYTES, "subject exceeds {MAX_SUBJECT_BYTES} bytes");
        if let Some(request) = &self.request {
            ensure!(request.len() <= MAX_SUBJECT_BYTES, "request exceeds {MAX_SUBJECT_BYTES} bytes");
        }
        ensure!(self.passages.len() <= MAX_PASSAGES, "at most {MAX_PASSAGES} passages");
        for p in &self.passages {
            ensure!(p.source.len() <= MAX_SOURCE_BYTES, "passage source exceeds {MAX_SOURCE_BYTES} bytes");
            ensure!(p.text.len() <= MAX_PASSAGE_BYTES, "passage text exceeds {MAX_PASSAGE_BYTES} bytes");
        }
        for field in [&self.context.architecture, &self.context.audience, &self.context.priorities]
            .into_iter()
            .flatten()
        {
            ensure!(field.len() <= MAX_CONTEXT_BYTES, "context field exceeds {MAX_CONTEXT_BYTES} bytes");
        }
        Ok(())
    }
}

/// Jev's typed answers. Probabilities are 0..=1; fit scores are 0..=3.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct ContentJudgment {
    pub deprecated: f64,
    pub already_decided: f64,
    pub contradicts_decision: f64,
    pub architecture_fit: f64,
    pub audience_fit: f64,
    pub attention: f64,
    pub scope_risk: f64,
    /// The priority (from the context) the content serves most, or "none".
    pub serves: String,
    /// Lowest confidence across the answers.
    pub min_confidence: f64,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum LearningReason {
    UsedDeprecated,
    ContradictedDecision,
    WeakArchitectureFit,
    MissedAudience,
    UserCorrected,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct LearningEvent {
    pub reasons: Vec<LearningReason>,
    /// Passage sources the judgment had in view; the lesson cites them.
    pub cited_sources: Vec<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct DecideOutput {
    pub kind: SubjectKind,
    pub judgment: ContentJudgment,
    /// Present only for a reply that crossed a learning threshold.
    pub learning_event: Option<LearningEvent>,
    pub model: String,
    pub judged_at: String,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct EmptyInput {}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ConfigOutput {
    pub endpoint: String,
    pub model: String,
    /// Whether a credential is configured; the key itself is never returned.
    pub credential_present: bool,
}

/// The learning rule: a reply that used something deprecated, contradicted a
/// decision, missed the architecture or audience, or drew a correction.
/// Requests never raise one.
pub fn classify_learning_event(
    kind: SubjectKind,
    judgment: &ContentJudgment,
    user_corrected: bool,
    passages: &[Passage],
) -> Option<LearningEvent> {
    if kind != SubjectKind::Reply {
        return None;
    }
    let mut reasons = Vec::new();
    if judgment.deprecated >= RAISED {
        reasons.push(LearningReason::UsedDeprecated);
    }
    if judgment.contradicts_decision >= RAISED {
        reasons.push(LearningReason::ContradictedDecision);
    }
    if judgment.architecture_fit < WEAK {
        reasons.push(LearningReason::WeakArchitectureFit);
    }
    if judgment.audience_fit < WEAK {
        reasons.push(LearningReason::MissedAudience);
    }
    if user_corrected {
        reasons.push(LearningReason::UserCorrected);
    }
    (!reasons.is_empty()).then(|| LearningEvent {
        reasons,
        cited_sources: passages.iter().map(|p| p.source.clone()).collect(),
    })
}

fn questions(kind: SubjectKind) -> Value {
    let who = match kind {
        SubjectKind::Request => "the request",
        SubjectKind::Reply => "the chatbot's reply",
    };
    json!({
        "deprecated": { "type": "noul", "instructions": format!(
            "Does {who} rely on something the passages or architecture mark as deprecated, retired, superseded or removed?") },
        "already_decided": { "type": "noul", "instructions": format!(
            "Have the passages already decided what {who} is about (an owner decision or correction it should follow)?") },
        "contradicts_decision": { "type": "noul", "instructions": format!(
            "Does {who} contradict an owner decision or correction in the passages or architecture rules?") },
        "architecture_fit": { "type": "score", "instructions": format!(
            "How well does {who} fit the architecture?"), "criteria": [
            "Conflicts with it or uses a retired surface.", "Unclear or partly at odds.",
            "Fits, with minor caveats.", "Fits squarely and uses existing mechanisms."] },
        "audience_fit": { "type": "score", "instructions": format!(
            "How much does {who} matter to the audience?"), "criteria": [
            "Irrelevant to them.", "Indirect: plumbing they never see.",
            "Relevant: they would notice or benefit.", "Central: what they evaluate or need."] },
        "attention": { "type": "score", "instructions": format!(
            "Would {who} earn attention measured against the priorities?"), "criteria": [
            "No effect, or distracts.", "Small or indirect effect.",
            "Clearly strengthens one priority.", "Strongly advances a top priority."] },
        "scope_risk": { "type": "noul", "instructions": format!(
            "Could {who} destabilize what already works or expand scope beyond the priorities?") },
        "serves": { "type": "choice", "instructions": format!(
            "Does {who} serve one of the stated priorities?"), "criteria": {
            "priority": "Yes: it directly serves a stated priority.",
            "none": "No stated priority, or no priorities were given." } },
    })
}

fn noul(answers: &Value, key: &str) -> Result<(f64, f64)> {
    let a = &answers[key];
    let value = a["noul"].as_f64().with_context(|| format!("jev answer {key} lacks a probability"))?;
    Ok((value.clamp(0.0, 1.0), a["confidence"].as_f64().unwrap_or(0.0)))
}
fn score(answers: &Value, key: &str) -> Result<(f64, f64)> {
    let a = &answers[key];
    let value = a["score"].as_f64().with_context(|| format!("jev answer {key} lacks a score"))?;
    Ok((value.clamp(0.0, 3.0), a["confidence"].as_f64().unwrap_or(0.0)))
}

/// Parse the System One `answers` object into a judgment.
pub fn judgment_from_answers(answers: &Value) -> Result<ContentJudgment> {
    let (deprecated, c1) = noul(answers, "deprecated")?;
    let (already_decided, c2) = noul(answers, "already_decided")?;
    let (contradicts_decision, c3) = noul(answers, "contradicts_decision")?;
    let (architecture_fit, c4) = score(answers, "architecture_fit")?;
    let (audience_fit, c5) = score(answers, "audience_fit")?;
    let (attention, c6) = score(answers, "attention")?;
    let (scope_risk, c7) = noul(answers, "scope_risk")?;
    let serves = answers["serves"]["choice"].as_str().unwrap_or("none").to_string();
    let min_confidence = [c1, c2, c3, c4, c5, c6, c7].into_iter().fold(1.0_f64, f64::min);
    Ok(ContentJudgment {
        deprecated,
        already_decided,
        contradicts_decision,
        architecture_fit,
        audience_fit,
        attention,
        scope_risk,
        serves,
        min_confidence,
    })
}

// No Debug/Serialize: the key never becomes output or a debug representation.
struct Credential(String);

fn credential() -> Option<Credential> {
    KEY_VARS.iter().find_map(|var| {
        std::env::var(var)
            .ok()
            .map(|v| v.trim().to_string())
            .filter(|v| !v.is_empty())
            .map(Credential)
    })
}

fn model() -> String {
    std::env::var("JEV_MODEL")
        .ok()
        .filter(|m| !m.trim().is_empty())
        .unwrap_or_else(|| DEFAULT_MODEL.to_string())
}

fn bounded_client() -> Result<Client> {
    Ok(Client::builder()
        .redirect(reqwest::redirect::Policy::none())
        .connect_timeout(Duration::from_secs(5))
        .timeout(Duration::from_secs(20))
        .no_proxy()
        .build()?)
}

async fn decide(input: DecideInput) -> Result<DecideOutput> {
    input.validate()?;
    let key = credential().context("jev credential is not configured (JEV_TYPESAFE_API_KEY)")?;
    let model = model();
    let state = json!({
        "subject_kind": input.kind,
        "subject": input.subject,
        "request": input.request,
        "passages": input.passages,
        "architecture": input.context.architecture,
        "audience": input.context.audience,
        "priorities": input.context.priorities,
    });
    let response = bounded_client()?
        .post(JEV_ENDPOINT)
        .bearer_auth(&key.0)
        .json(&json!({ "model": model, "state": state, "questions": questions(input.kind) }))
        .send()
        .await
        .context("jev request failed")?;
    let status = response.status();
    ensure!(status.is_success(), "jev returned HTTP {}", status.as_u16());
    let body: Value = response.json().await.context("jev response is not JSON")?;
    let judgment = judgment_from_answers(&body["answers"])?;
    let learning_event =
        classify_learning_event(input.kind, &judgment, input.user_corrected, &input.passages);
    Ok(DecideOutput {
        kind: input.kind,
        judgment,
        learning_event,
        model: body["model"].as_str().map(str::to_string).unwrap_or(model),
        judged_at: chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, true),
    })
}

pub fn config() -> ConfigOutput {
    ConfigOutput {
        endpoint: JEV_ENDPOINT.to_string(),
        model: model(),
        credential_present: credential().is_some(),
    }
}

/// Canonical dispatch; the bridge has already admitted the caller and
/// validated `args` against the sealed contract.
pub async fn dispatch_jev_method(method: &str, args: &serde_json::Value) -> Result<serde_json::Value> {
    match method {
        "decide" => {
            let input: DecideInput = serde_json::from_value(args.clone())
                .context("jev decide input does not match its schema")?;
            Ok(serde_json::to_value(decide(input).await?)?)
        }
        "get_config" => Ok(serde_json::to_value(config())?),
        other => anyhow::bail!("jev has no method {other}"),
    }
}

