    }
    fn version(&self) -> &str {
        VERSION
    }
    fn schema(&self) -> Option<PluginSchema> {
        Some(jev_schema())
    }
    async fn calculate_diff(&self, _: &Value, _: &Value) -> Result<StateDiff> {
        bail!("jev is stateless; call decide")
    }
    async fn apply_state(&self, _: &StateDiff) -> Result<ApplyResult> {
        bail!("jev is stateless; call decide")
    }
    async fn verify_state(&self, _: &Value) -> Result<bool> {
        Ok(false)
    }
    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        bail!("jev has no checkpoint surface")
    }
    async fn rollback(&self, _: &Checkpoint) -> Result<()> {
        bail!("jev has no rollback surface")
    }
    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: false,
            supports_verification: false,
            atomic_operations: false,
        }
    }
}

pub fn jev_schema() -> PluginSchema {
    use super::plugin_scaffold_helpers::method_decl_from_schemars_with_output;
    use methods::{ConfigOutput, DecideInput, DecideOutput, EmptyInput};
    let root = serde_json::to_value(schemars::schema_for!(JevState)).expect("jev state schema serializes");
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        NAME,
        VERSION,
        "Jev content judgments for recorded chat: deprecation, decisions, fit, attention, learning events",
        &root,
    );
    schema.category = "governance".into();
    // decide sends content to the pinned Jev origin: an external effect, not a read.
    schema.methods.insert(
        "decide".into(),
        method_decl_from_schemars_with_output::<DecideInput, DecideOutput>(
            "decide",
            SideEffect::Mutation,
            false,
            INVOKE_CAP,
            "mut.service.jev.decide@v1",
        ),
    );
    schema.methods.insert(
        "get_config".into(),
        method_decl_from_schemars_with_output::<EmptyInput, ConfigOutput>(
            "get_config",
            SideEffect::Read,
            true,
            READ_CAP,
            "obs.service.jev.config.get@v1",
        ),
    );
    for (id, description) in [
        (INVOKE_CAP, "Send recorded chat content to Jev for a content judgment"),
        (READ_CAP, "Read the nonsecret Jev configuration"),
    ] {
        schema
            .capabilities
            .insert(id.into(), CapabilityDecl { id: id.into(), description: description.into() });
    }
    super::common::oscal::ensure_category_metadata_fields(&mut schema);
    schema
}

inventory::submit! {
    crate::default_registry::PluginReg::new(NAME, |_ctx| std::sync::Arc::new(JevPlugin))
}

