//! Jev content judgment of a completed chat reply, recorded on its episode.
//!
//! Content decisions only: the judgment never blocks, reroutes or edits the
//! reply. Routing stays with the schema router and OpenFlow.
//!
//! Gates, all required:
//! - the chat mode is a recorded working mode (Project, Accountability,
//!   ControlPlane, NotebookLm). Personal content is never sent to Jev, and
//!   UiRender records no episode;
//! - the verified caller holds `jev.invoke`, so judging is opt-in per identity;
//! - a Jev credential is configured.
//!
//! Reference passages come only from the caller's own scoped episodes: lessons
//! (`learning_event`) first, then term overlap with the request. Fail-open:
//! any error or timeout records the episode without a judgment.

use std::collections::HashSet;
use std::time::Duration;

use op_cozo_store::EpisodeScope;
use op_plugins::state_plugins::ctl_plane_chatbot::ReasoningEpisode;
use op_plugins::state_plugins::jev::{
    self,
    methods::{DecideContext, DecideInput, DecideOutput, Passage, SubjectKind},
};
use op_plugins::state_plugins::project::ChatMode;

use crate::mutation_engine::MutationEngine;

const JUDGE_TIMEOUT: Duration = Duration::from_secs(10);
const SCAN: usize = 199;
const KEEP: usize = 6;
const PASSAGE_BYTES: usize = 1_400;
const SUBJECT_BYTES: usize = 7_900;

const ARCHITECTURE: &str = "The plugin is the schema: every capability is a sealed-blob plugin. \
Identities act only through their own 3tchedFS call files, admitted by the bridge with receipts; \
no MCP, no direct API bypass, no alternate transport. D-Bus is the control plane. Rust backend; \
Svelte + json-render UI. Retired surfaces must not be restored.";

pub(crate) fn judged_mode(mode: ChatMode) -> bool {
    matches!(
        mode,
        ChatMode::Project | ChatMode::Accountability | ChatMode::ControlPlane | ChatMode::NotebookLm
    )
}

fn clip(text: &str, max: usize) -> String {
    if text.len() <= max {
        return text.to_string();
    }
    let mut end = max;
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}…", &text[..end.saturating_sub(3)])
}

fn terms(text: &str) -> HashSet<String> {
    text.split(|c: char| !c.is_alphanumeric() && c != '_' && c != '-')
        .filter(|w| w.len() >= 5)
        .map(str::to_lowercase)
        .collect()
}

/// Rank the caller's own episodes as reference passages for `request`.
fn passages(episodes: Vec<ReasoningEpisode>, request: &str) -> Vec<Passage> {
    let wanted = terms(request);
    let mut ranked: Vec<(f64, ReasoningEpisode)> = episodes
        .into_iter()
        .filter(|e| e.goal_text.is_some() || e.decision_output.is_some())
        .map(|e| {
            let text = format!(
                "{} {}",
                e.goal_text.as_deref().unwrap_or(""),
                e.decision_output.as_deref().unwrap_or("")
            );
            let overlap = terms(&text).intersection(&wanted).count() as f64;
            let lesson = if e.learning_event.is_some() { 5.0 } else { 0.0 };
            (overlap + lesson, e)
        })
        .filter(|(score, _)| *score > 0.0)
        .collect();
    ranked.sort_by(|a, b| b.0.total_cmp(&a.0));
    ranked
        .into_iter()
        .take(KEEP)
        .map(|(_, e)| {
            let lesson = e
                .learning_event
                .as_ref()
                .map(|l| format!(" [lesson: {}]", serde_json::to_string(&l.reasons).unwrap_or_default()))
                .unwrap_or_default();
            Passage {
                source: clip(&format!("episode {} {}", e.episode_id, e.started_at), 250),
                text: clip(
                    &format!(
                        "asked: {} | answered: {}{lesson}",
                        e.goal_text.as_deref().unwrap_or(""),
                        e.decision_output.as_deref().unwrap_or("")
                    ),
                    PASSAGE_BYTES,
                ),
            }
        })
        .collect()
}

/// Judge `reply` (the chatbot's answer to `request`) for the episode about to
/// be recorded. `None` when a gate is closed or Jev fails.
pub(crate) async fn judge_reply(
    engine: &MutationEngine,
    mode: ChatMode,
    actor: &str,
    scope: &EpisodeScope,
    request: Option<&str>,
    reply: &str,
) -> Option<DecideOutput> {
    if !judged_mode(mode)
        || reply.trim().is_empty()
        || !crate::interceptor::load_capability_grants(actor).contains(jev::INVOKE_CAP)
        || !jev::methods::config().credential_present
    {
        return None;
    }
    let request = request.unwrap_or("");
    let history = match engine.ctl_plane_chatbot_episode_cozo().await {
        Ok(store) => {
            let page_scope = scope.clone();
            tokio::task::spawn_blocking(move || store.list_scoped_episode_page(&page_scope, None, SCAN))
                .await
                .ok()
                .and_then(Result::ok)
                .map(|page| {
                    page.episodes
                        .into_iter()
                        .filter_map(|row| serde_json::from_value::<ReasoningEpisode>(row.episode).ok())
                        .collect()
                })
                .unwrap_or_default()
        }
        Err(_) => Vec::new(),
    };
    let input = DecideInput {
        subject: clip(reply, SUBJECT_BYTES),
        kind: SubjectKind::Reply,
        request: (!request.is_empty()).then(|| clip(request, SUBJECT_BYTES)),
        user_corrected: false,
        passages: passages(history, request),
        context: DecideContext {
            architecture: Some(ARCHITECTURE.to_string()),
            audience: Some(format!("The verified human in this {mode:?} conversation and the project it serves.")),
            priorities: None,
        },
    };
    match tokio::time::timeout(JUDGE_TIMEOUT, jev::methods::decide(input)).await {
        Ok(Ok(output)) => Some(output),
        Ok(Err(error)) => {
            tracing::warn!(%error, "jev judgment failed; episode recorded without it");
            None
        }
        Err(_) => {
            tracing::warn!("jev judgment timed out; episode recorded without it");
            None
        }
    }
}

