//! Jev content judgment of a completed chat reply, recorded on its episode.
//!
//! Content decisions only: the judgment never blocks, reroutes or edits the
//! reply. Routing stays with the schema router and OpenFlow.
//!
//! Gates, all required:
//! - the chat mode is a recorded working mode (Project, Accountability,
//!   ControlPlane, NotebookLm). Personal content is never sent to Jev, and
//!   UiRender records no episode;
//! - the verified caller holds `jev.invoke`, so judging is opt-in per identity;
//! - a Jev credential is configured.
//!
//! Reference passages come only from the caller's own scoped episodes: lessons
//! (`learning_event`) first, then term overlap with the request. Fail-open:
//! any error or timeout records the episode without a judgment.

use std::collections::HashSet;
use std::time::Duration;

use op_cozo_store::EpisodeScope;
use op_plugins::state_plugins::ctl_plane_chatbot::ReasoningEpisode;
use op_plugins::state_plugins::jev::{
    self,
    methods::{DecideContext, DecideInput, DecideOutput, Passage, SubjectKind},
};
use op_plugins::state_plugins::project::ChatMode;

use crate::mutation_engine::MutationEngine;

const JUDGE_TIMEOUT: Duration = Duration::from_secs(10);
const SCAN: usize = 199;
const KEEP: usize = 6;
const PASSAGE_BYTES: usize = 1_400;
const SUBJECT_BYTES: usize = 7_900;

const ARCHITECTURE: &str = "The plugin is the schema: every capability is a sealed-blob plugin. \
Identities act only through their own 3tchedFS call files, admitted by the bridge with receipts; \
no MCP, no direct API bypass, no alternate transport. D-Bus is the control plane. Rust backend; \
Svelte + json-render UI. Retired surfaces must not be restored.";

pub(crate) fn judged_mode(mode: ChatMode) -> bool {
    matches!(
        mode,
        ChatMode::Project | ChatMode::Accountability | ChatMode::ControlPlane | ChatMode::NotebookLm
    )
}

fn clip(text: &str, max: usize) -> String {
    if text.len() <= max {
        return text.to_string();
    }
    let mut end = max;
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}…", &text[..end.saturating_sub(3)])
}

fn terms(text: &str) -> HashSet<String> {
    text.split(|c: char| !c.is_alphanumeric() && c != '_' && c != '-')
        .filter(|w| w.len() >= 5)
        .map(str::to_lowercase)
        .collect()
}

/// Rank the caller's own episodes as reference passages for `request`.
fn passages(episodes: Vec<ReasoningEpisode>, request: &str) -> Vec<Passage> {
    let wanted = terms(request);
    let mut ranked: Vec<(f64, ReasoningEpisode)> = episodes
        .into_iter()
        .filter(|e| e.goal_text.is_some() || e.decision_output.is_some())
        .map(|e| {
            let text = format!(
                "{} {}",
                e.goal_text.as_deref().unwrap_or(""),
                e.decision_output.as_deref().unwrap_or("")
            );
            let overlap = terms(&text).intersection(&wanted).count() as f64;
            let lesson = if e.learning_event.is_some() { 5.0 } else { 0.0 };
            (overlap + lesson, e)
        })
        .filter(|(score, _)| *score > 0.0)
        .collect();
    ranked.sort_by(|a, b| b.0.total_cmp(&a.0));
    ranked
        .into_iter()
        .take(KEEP)
        .map(|(_, e)| {
            let lesson = e
                .learning_event
                .as_ref()
                .map(|l| format!(" [lesson: {}]", serde_json::to_string(&l.reasons).unwrap_or_default()))
                .unwrap_or_default();
            Passage {
                source: clip(&format!("episode {} {}", e.episode_id, e.started_at), 250),
                text: clip(
                    &format!(
                        "asked: {} | answered: {}{lesson}",
                        e.goal_text.as_deref().unwrap_or(""),
                        e.decision_output.as_deref().unwrap_or("")
                    ),
                    PASSAGE_BYTES,
                ),
            }
        })
        .collect()
}

/// Judge `reply` (the chatbot's answer to `request`) for the episode about to
/// be recorded. `None` when a gate is closed or Jev fails.
pub(crate) async fn judge_reply(
    engine: &MutationEngine,
    mode: ChatMode,
    actor: &str,
    scope: &EpisodeScope,
    request: Option<&str>,
    reply: &str,
) -> Option<DecideOutput> {
    if !judged_mode(mode)
        || reply.trim().is_empty()
        || !crate::interceptor::load_capability_grants(actor).contains(jev::INVOKE_CAP)
        || !jev::methods::config().credential_present
    {
        return None;
    }
    let request = request.unwrap_or("");
    let history = match engine.ctl_plane_chatbot_episode_cozo().await {
        Ok(store) => {
            let page_scope = scope.clone();
            tokio::task::spawn_blocking(move || store.list_scoped_episode_page(&page_scope, None, SCAN))
                .await
                .ok()
                .and_then(Result::ok)
                .map(|page| {
                    page.episodes
                        .into_iter()
                        .filter_map(|row| serde_json::from_value::<ReasoningEpisode>(row.episode).ok())
                        .collect()
                })
                .unwrap_or_default()
        }
        Err(_) => Vec::new(),
    };
    let input = DecideInput {
        subject: clip(reply, SUBJECT_BYTES),
        kind: SubjectKind::Reply,
        request: (!request.is_empty()).then(|| clip(request, SUBJECT_BYTES)),
        user_corrected: false,
        passages: passages(history, request),
        context: DecideContext {
            architecture: Some(ARCHITECTURE.to_string()),
            audience: Some(format!("The verified human in this {mode:?} conversation and the project it serves.")),
            priorities: None,
        },
    };
    match tokio::time::timeout(JUDGE_TIMEOUT, jev::methods::decide(input)).await {
        Ok(Ok(output)) => Some(output),
        Ok(Err(error)) => {
            tracing::warn!(%error, "jev judgment failed; episode recorded without it");
            None
        }
        Err(_) => {
            tracing::warn!("jev judgment timed out; episode recorded without it");
            None
        }
    }
}

//! Jev content-decision plugin: typed judgments about recorded chat content.
//!
//! Judges content only: deprecated, already decided, contradicts a decision,
//! architecture and audience fit, attention, scope risk, and — for the
//! chatbot's own replies — whether a learning event is raised. It does not
//! route; OpenFlow and the schema router own routing. Stateless: the caller
//! supplies reference passages, and records the judgment with the content.

use anyhow::{Result, bail};
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::{CapabilityDecl, PluginSchema, SideEffect};
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;

#[path = "jev_methods.rs"]
pub mod methods;
pub use methods::dispatch_jev_method;

const NAME: &str = "jev";
const VERSION: &str = "0.1.0";
pub const INVOKE_CAP: &str = "jev.invoke";
pub const READ_CAP: &str = "jev.read";

/// Declared state: the nonsecret configuration only.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.jev.schema@v1"))]
pub struct JevState {
    pub endpoint: String,
    pub model: String,
    pub credential_present: bool,
}

pub struct JevPlugin;

#[async_trait]
impl StatePlugin for JevPlugin {
    fn name(&self) -> &str {
        NAME
    }
    fn version(&self) -> &str {
        VERSION
    }
    fn schema(&self) -> Option<PluginSchema> {
        Some(jev_schema())
    }
    async fn calculate_diff(&self, _: &Value, _: &Value) -> Result<StateDiff> {
        bail!("jev is stateless; call decide")
    }
    async fn apply_state(&self, _: &StateDiff) -> Result<ApplyResult> {
        bail!("jev is stateless; call decide")
    }
    async fn verify_state(&self, _: &Value) -> Result<bool> {
        Ok(false)
    }
    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        bail!("jev has no checkpoint surface")
    }
    async fn rollback(&self, _: &Checkpoint) -> Result<()> {
        bail!("jev has no rollback surface")
    }
    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: false,
            supports_verification: false,
            atomic_operations: false,
        }
    }
}

pub fn jev_schema() -> PluginSchema {
    use super::plugin_scaffold_helpers::method_decl_from_schemars_with_output;
    use methods::{ConfigOutput, DecideInput, DecideOutput, EmptyInput};
    let root = serde_json::to_value(schemars::schema_for!(JevState)).expect("jev state schema serializes");
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        NAME,
        VERSION,
        "Jev content judgments for recorded chat: deprecation, decisions, fit, attention, learning events",
        &root,
    );
    schema.category = "governance".into();
    // decide sends content to the pinned Jev origin: an external effect, not a read.
    schema.methods.insert(
        "decide".into(),
        method_decl_from_schemars_with_output::<DecideInput, DecideOutput>(
            "decide",
            SideEffect::Mutation,
            false,
            INVOKE_CAP,
            "mut.service.jev.decide@v1",
        ),
    );
    schema.methods.insert(
        "get_config".into(),
        method_decl_from_schemars_with_output::<EmptyInput, ConfigOutput>(
            "get_config",
            SideEffect::Read,
            true,
            READ_CAP,
            "obs.service.jev.config.get@v1",
        ),
    );
    for (id, description) in [
        (INVOKE_CAP, "Send recorded chat content to Jev for a content judgment"),
        (READ_CAP, "Read the nonsecret Jev configuration"),
    ] {
        schema
            .capabilities
            .insert(id.into(), CapabilityDecl { id: id.into(), description: description.into() });
    }
    super::common::oscal::ensure_category_metadata_fields(&mut schema);
    schema
}

inventory::submit! {
    crate::default_registry::PluginReg::new(NAME, |_ctx| std::sync::Arc::new(JevPlugin))
}

// jev-decisions — project-local omp extension for the hackathon.
//
// Before each turn, Jev judges the request against the gathered conversation
// corpus (the NotebookLM-synced ledger, searched by ~/.jev-router) and this
// project's own rules and judging criteria, then hands the model a short note:
// is it deprecated or already decided, does it fit the architecture, does it
// serve the target audience, will it get the judges' attention.
//
// Advisory only: it never switches models or blocks a turn. The `jev_decide`
// tool runs the same check on a specific proposal mid-turn (a design choice, a
// feature, a dependency). `/jev-decide off|on|status` toggles the per-turn note.
// Fail-open: any error leaves the turn unchanged.

import { existsSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";

const HOME = process.env.HOME ?? "";
const ROUTER = process.env.JEV_ROUTER_DIR || `${HOME}/.jev-router`;
const HACKATHON = path.resolve(import.meta.dirname, "..", "..", "..");
const OFF = path.join(HACKATHON, ".omp", "jev-decisions.off");

type Question =
  | { type: "noul"; instructions: string; criteria?: { true?: string; false?: string } }
  | { type: "choice"; instructions: string; criteria: Record<string, string> }
  | { type: "score"; instructions: string; criteria: string[] };

// Project context Jev judges against. Read once per process; files are the source of truth.
function excerpt(rel: string, max: number): string {
  try {
    return readFileSync(path.join(HACKATHON, rel), "utf8").slice(0, max);
  } catch {
    return "";
  }
}
const CONTEXT = {
  target_audience:
    "Judges of Meta's Model API hackathon, Startup Track (they reward a working product, visible and good use of Meta's Muse Spark model, and verifiable claims); and the product's users: a small regulated business that needs a compliant client portal/CMS run by an AI identity that cannot exceed its permissions.",
  architecture: excerpt("AGENTS.md", 3500),
  start_here: excerpt("START-HERE.md", 3000),
  judging_priorities: excerpt("docs/WINNING.md", 4000),
};

const QUESTIONS: Record<string, Question> = {
  deprecated: {
    type: "noul",
    instructions:
      "Does the subject rely on something that past_conversations or the architecture mark as deprecated, retired, superseded or removed (e.g. MCP, retired services, old names)?",
  },
  already_decided: {
    type: "noul",
    instructions: "Have past_conversations already decided this (an owner decision or correction that the subject should follow or would contradict)?",
  },
  contradicts_decision: {
    type: "noul",
    instructions: "Would doing the subject contradict an owner decision or correction found in past_conversations or the architecture rules?",
  },
  architecture_fit: {
    type: "score",
    instructions:
      "How well does the subject fit the stated architecture (sealed-blob plugins, identity acting only through 3tchedFS call files with receipts, Rust backend, Svelte + json-render UI, no MCP, no direct API bypass)?",
    criteria: [
      "Conflicts with it: bypasses identity/receipts, uses a retired surface, or adds a parallel path.",
      "Unclear or partly at odds.",
      "Fits, with minor caveats.",
      "Fits squarely and uses the existing mechanisms.",
    ],
  },
  audience_fit: {
    type: "score",
    instructions: "How much does the subject matter to the target_audience?",
    criteria: [
      "Invisible or irrelevant to judges and users.",
      "Indirect: internal plumbing they never see.",
      "Relevant: they would notice or benefit.",
      "Central: directly what they evaluate or need.",
    ],
  },
  judge_attention: {
    type: "score",
    instructions:
      "Would the subject help win the judges' attention, measured against judging_priorities (first 30 seconds, verifiable receipts, a live refusal, visible Muse Spark use, golden-path reliability, redaction, fallbacks, the business story, the positioning line, shipped evidence)?",
    criteria: [
      "No effect, or distracts from the demo.",
      "Small or indirect effect.",
      "Clearly strengthens one priority.",
      "Strongly advances a top priority on stage.",
    ],
  },
  golden_path_risk: {
    type: "noul",
    instructions:
      "Could the subject destabilize the golden path (intro → create a CMS → provision → receipts → anchor) or expand scope beyond what the priorities support?",
  },
  priority: {
    type: "choice",
    instructions: "Which judging priority does the subject serve most?",
    criteria: {
      first_30s: "Unforgettable first 30 seconds.",
      verifiable: "A judge verifies something themselves (receipt, anchor).",
      refusal: "A live refusal at the OSCAL boundary.",
      meta_model: "Visible, good use of Meta's Muse Spark.",
      golden_path: "Protecting the golden path's reliability.",
      redaction: "Automatic redaction with a policy receipt.",
      fallback: "A fallback for a live dependency.",
      story: "The real-business story.",
      positioning: "The positioning line.",
      evidence: "Shipped evidence: README, video, diagram, live link.",
      none: "None of these.",
    },
  },
};

interface Verdict {
  deprecated: number;
  alreadyDecided: number;
  contradicts: number;
  architecture: number;
  audience: number;
  attention: number;
  goldenPathRisk: number;
  priority: string;
  passages: { source: string; text: string }[];
}

let mod: any = null;
async function router() {
  mod ??= await import(`${ROUTER}/src/judge.ts`);
  return mod;
}

async function decide(subject: string, history?: unknown): Promise<Verdict | null> {
  const m = await router();
  let passages: { source: string; text: string }[] = [];
  try {
    passages = await m.searchCollection(subject, 4, 6000);
  } catch {
    /* corpus unavailable: judge on project context alone */
  }
  const a = await m.judge(
    { subject: subject.slice(0, 3000), recent_history: history ?? null, past_conversations: passages, ...CONTEXT },
    QUESTIONS,
    12_000,
  );
  if (!a) return null;
  const n = (k: string) => (a[k]?.type === "noul" ? Number(a[k].noul) : 0);
  const s = (k: string) => (a[k]?.type === "score" ? Number(a[k].score) : 0);
  return {
    deprecated: n("deprecated"),
    alreadyDecided: n("already_decided"),
    contradicts: n("contradicts_decision"),
    architecture: s("architecture_fit"),
    audience: s("audience_fit"),
    attention: s("judge_attention"),
    goldenPathRisk: n("golden_path_risk"),
    priority: a.priority?.type === "choice" ? String(a.priority.choice) : "none",
    passages,
  };
}

const pct = (v: number) => `${Math.round(v * 100)}%`;
function render(v: Verdict): string {
  const flags: string[] = [];
  if (v.deprecated >= 0.7) flags.push("relies on something DEPRECATED — check the passages and use the current replacement");
  if (v.contradicts >= 0.7) flags.push("would CONTRADICT an owner decision — follow the decision or ask");
  else if (v.alreadyDecided >= 0.7) flags.push("ALREADY DECIDED — follow the earlier decision rather than re-deciding");
  if (v.architecture < 1.5) flags.push("weak ARCHITECTURE fit — route through sealed plugins / 3tchedFS call files with receipts");
  if (v.goldenPathRisk >= 0.7) flags.push("GOLDEN-PATH RISK — keep it off the demo path or justify it");
  if (v.audience < 1.5 && v.attention < 1.5) flags.push("low value to judges/users — consider deprioritizing");
  return [
    "Jev decision check (advisory; grounded in the conversation corpus + project rules):",
    `deprecated ${pct(v.deprecated)} · decided ${pct(v.alreadyDecided)} · contradicts ${pct(v.contradicts)} · ` +
      `architecture ${v.architecture.toFixed(1)}/3 · audience ${v.audience.toFixed(1)}/3 · judges ${v.attention.toFixed(1)}/3 · ` +
      `golden-path risk ${pct(v.goldenPathRisk)} · serves: ${v.priority}`,
    ...flags.map((f) => `- ${f}`),
    ...(v.passages.length
      ? ["Relevant past conversations:", ...v.passages.map((p) => `  • ${p.source}: ${p.text.slice(0, 400)}`)]
      : ["No matching past conversations."]),
    "Cite a passage when you follow or depart from it. These are judgments, not facts: verify against current code and docs.",
  ].join("\n");
}

function promptText(prompt: unknown): string {
  if (typeof prompt === "string") return prompt;
  if (Array.isArray(prompt)) return prompt.map((b: any) => (b?.type === "text" ? b.text : "")).join("\n");
  return "";
}

export default function jevDecisions(pi: any) {
  pi.setLabel?.("Jev Decisions");
  const status = (ctx: any, text: string) => ctx?.ui?.setStatus?.("jev-decide", text);

  pi.on("before_agent_start", async (event: { prompt?: unknown }, ctx: any) => {
    if (existsSync(OFF)) return;
    const text = promptText(event.prompt).trim();
    if (text.length < 8) return;
    const t0 = Date.now();
    try {
      let history: unknown;
      try {
        const m = await router();
        const file = ctx?.sessionManager?.getSessionFile?.();
        if (file) history = m.historyFromOmpSession(readFileSync(file, "utf8"));
      } catch {
        /* no history */
      }
      const v = await decide(text, history);
      if (!v) {
        status(ctx, "jev decide: unavailable");
        return;
      }
      status(ctx, `jev decide · judges ${v.attention.toFixed(1)}/3 · arch ${v.architecture.toFixed(1)}/3 · ${Date.now() - t0}ms`);
      return { message: { customType: "jev-decision-check", content: render(v), display: true } };
    } catch {
      status(ctx, "jev decide: error, turn unchanged");
      return;
    }
  });

  pi.registerTool({
    name: "jev_decide",
    label: "Jev Decide",
    description:
      "Before committing to a design choice, feature, dependency or demo change, ask Jev to judge the proposal against the gathered conversation history (owner decisions, deprecations) and this project's architecture, target audience and judging priorities. Returns deprecated / already-decided / contradicts-decision probabilities, architecture, audience and judge-attention scores, golden-path risk, the priority it serves, and the past-conversation passages it relied on. Advisory: verify against current code.",
    parameters: pi.zod.object({
      proposal: pi.zod.string().describe("The specific proposal, in one or a few sentences, with any names it depends on."),
    }),
    async execute(_id: string, params: { proposal: string }) {
      const v = await decide(params.proposal);
      const text = v ? render(v) : "Jev unavailable (no TYPESAFE key or the request failed); decide without it.";
      return { content: [{ type: "text", text }], details: v };
    },
  });

  pi.registerCommand?.("jev-decide", {
    description: "Per-turn Jev decision check: on | off | status",
    handler: async (args: string, ctx: any) => {
      const a = (args || "").trim().toLowerCase();
      if (a === "off") writeFileSync(OFF, "off\n");
      else if (a === "on") rmSync(OFF, { force: true });
      ctx?.ui?.notify?.(`Jev decision check ${existsSync(OFF) ? "off" : "on"}`, "info");
    },
  });
}

// omp extension: lets omp delegate work to the Muse Code agent over MSP.
//
// Registers the `muse_code` tool and the `/muse` command. One `muse serve`
// host is spawned lazily and reused; sessions persist, so omp can continue
// one with `session_id`. Approvals go through the shared client policy
// (policy.ts); anything it cannot decide is put to the person in omp's UI,
// or denied when no UI is attached. Loaded from
// `hackathon/.omp/extensions/muse-code/` so imports resolve here.

import path from "node:path";
import { MuseClient, checkServedFingerprint, type Session } from "@muse-code/sdk";
import { deny, evaluate, type ApprovalRequestView } from "./policy.ts";

// The subset of omp's ExtensionAPI this file uses (its types are not installed here).
interface Ui {
  notify(message: string, level?: "info" | "warning" | "error"): void;
  select?(title: string, options: string[]): Promise<string | undefined>;
  input?(title: string, placeholder?: string): Promise<string | undefined>;
  setStatus?(key: string, text: string | undefined): void;
}
interface Ctx { readonly ui: Ui; readonly hasUI?: boolean; readonly cwd?: string }
type ToolResult = { content: { type: "text"; text: string }[]; details?: unknown };
interface Api {
  // omp passes its own zod; typed loosely so this package needs no zod dependency.
  readonly zod: any;
  setLabel(label: string): void;
  on(event: string, handler: (event: unknown, ctx: Ctx) => unknown): void;
  registerTool(tool: {
    name: string;
    label: string;
    description: string;
    parameters: unknown;
    execute(
      id: string,
      params: Params,
      signal?: AbortSignal,
      onUpdate?: (partial: ToolResult) => void,
      ctx?: Ctx,
    ): Promise<ToolResult>;
  }): void;
  registerCommand(name: string, cmd: { description: string; handler(args: string, ctx: Ctx): Promise<void> }): void;
  sendMessage(msg: { customType: string; content: string; display: boolean }, opts?: { triggerTurn?: boolean }): void;
}
interface Params {
  task: string;
  session_id?: string;
  effort?: "none" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max" | "ultra";
  allow_writes?: boolean;
  allow_shell?: boolean;
}

const HACKATHON = path.resolve(import.meta.dirname, "..", "..");

export default function museCode(pi: Api) {
  const z = pi.zod;
  pi.setLabel("Muse Code");

  let client: Promise<MuseClient> | undefined;
  const sessions = new Map<string, Session>();
  let uiCtx: Ctx | undefined;
  let allow = { writes: false, shell: false };

  function host(): Promise<MuseClient> {
    client ??= MuseClient.spawn({
      museBin: process.env.MUSE_BIN ?? "muse",
      args: ["serve", ...(process.env.MUSE_MODEL ? ["--model", process.env.MUSE_MODEL] : [])],
      cwd: HACKATHON,
      env: process.env,
      clientInfo: { name: "etched_omp", version: "0.1.0" },
      // No MCP: this project acts only through 3tchedFS.
      capabilities: { requestedCapabilities: ["feedback", "sessionRename"], userInputDialogs: true },
    }).then((c) => {
      const fp = checkServedFingerprint(c.initializeResult.schema.fingerprint);
      if (fp) uiCtx?.ui.notify(fp.message, "warning");
      void c.exit.then((exit) => {
        client = undefined;
        sessions.clear();
        if (exit.kind !== "cleanShutdown") uiCtx?.ui.notify(`muse host exited: ${exit.kind}`, "error");
      });
      return c;
    }, (e: unknown) => {
      client = undefined;
      throw e;
    });
    return client;
  }

  async function onApproval(raw: unknown) {
    const request = raw as ApprovalRequestView;
    const verdict = evaluate(request, {
      workspaceRoots: [HACKATHON],
      allowWrites: allow.writes,
      allowShell: allow.shell,
      allowNetwork: false,
    });
    if (verdict.kind === "decide") return verdict.decision;
    const ui = uiCtx?.ui;
    if (uiCtx?.hasUI !== false && ui?.select) {
      const labels = request.availableChoices.map((c) => `${c.label} (${c.scope})${c.rulePreview ? ` — ${c.rulePreview}` : ""}`);
      const picked = await ui.select(`Muse wants ${request.toolName}: ${verdict.why}`, labels);
      const choice = request.availableChoices[picked === undefined ? -1 : labels.indexOf(picked)];
      if (choice) {
        const feedback = choice.acceptsFeedback && ui.input ? await ui.input("Feedback for Muse (optional)") : undefined;
        return feedback ? { choiceId: choice.choiceId, feedback } : { choiceId: choice.choiceId };
      }
    }
    const d = deny(request, `no decision from omp (${verdict.why})`);
    if (d.kind === "decide") return d.decision;
    throw new Error(`approval could not be decided: ${verdict.why}`);
  }

  async function answerQuestions(session: Session, asked: Set<string>) {
    const ui = uiCtx?.ui;
    for (const p of session.fold.pendingUserInputs()) {
      if (asked.has(p.userInputId)) continue;
      asked.add(p.userInputId);
      const answers = [];
      for (const q of p.questions) {
        const labels = q.options.map((o) => o.label);
        const pick = ui?.select ? await ui.select(`Muse asks: ${q.question}`, [...labels, "Other…"]) : undefined;
        if (pick !== undefined && pick !== "Other…") {
          answers.push(q.selection.mode === "multiple" ? { questionId: q.id, selectedLabels: [pick] } : { questionId: q.id, selectedLabel: pick });
        } else {
          const text = (ui?.input ? await ui.input(q.question) : undefined) ?? "No answer available; use your best judgment.";
          answers.push({ questionId: q.id, freeText: text.slice(0, 500) });
        }
      }
      await session.answerUserInput(p.userInputId, answers);
    }
  }

  async function open(sessionId: string | undefined): Promise<Session> {
    const c = await host();
    if (sessionId) {
      const known = sessions.get(sessionId);
      if (known) return known;
      const s = await c.resumeSession({ sessionId, onApproval, onApprovalError: (f) => uiCtx?.ui.notify(`approval ${f.kind}`, "warning") });
      sessions.set(s.sessionId, s);
      return s;
    }
    const s = await c.startSession({ workspaceRoot: HACKATHON, recoveryMode: "on" });
    s.onApproval(onApproval);
    s.onApprovalError((f) => uiCtx?.ui.notify(`approval ${f.kind}`, "warning"));
    sessions.set(s.sessionId, s);
    return s;
  }

  async function run(params: Params, signal?: AbortSignal, onUpdate?: (r: ToolResult) => void): Promise<ToolResult> {
    allow = { writes: params.allow_writes === true, shell: params.allow_shell === true };
    const session = await open(params.session_id);
    const turn = await session.sendUserTurn({
      input: [{ type: "text", text: params.task }],
      ifBusy: "queue",
      ...(params.effort ? { reasoningEffort: params.effort } : {}),
    });
    const tools: string[] = [];
    const finalText = new Map<string, string>();
    let live = "";
    const asked = new Set<string>();
    const ticker = setInterval(() => void answerQuestions(session, asked).catch(() => undefined), 300);
    const onAbort = () => void client?.then((c) => c.close());
    signal?.addEventListener("abort", onAbort, { once: true });
    const update = () => onUpdate?.({ content: [{ type: "text", text: [...tools.slice(-5), live.slice(-1500)].join("\n") }] });

    const items = (async () => {
      for await (const item of turn.items()) {
        if (item.kind === "agentMessage" && item.text) finalText.set(item.itemId, item.text);
        if (item.kind === "toolCall" && item.status !== "inProgress") {
          tools.push(`▸ ${item.tool ?? "tool"} ${item.status}`);
          update();
        }
      }
    })();
    const deltas = (async () => {
      for await (const d of turn.deltas()) {
        if (d.field === undefined || d.field === "text") {
          live += d.delta;
          update();
        }
      }
    })();

    try {
      const outcome = await turn.completed;
      await Promise.allSettled([items, deltas]);
      const text = [...finalText.values()].join("\n\n") || live;
      const p = outcome.kind === "completed" ? outcome.params : undefined;
      const footer = [
        `muse session ${session.sessionId} (pass as session_id to continue)`,
        `terminal: ${p?.terminal ?? outcome.kind}${p?.error ? ` — ${p.error.kind}: ${p.error.message}` : ""}`,
        p?.usage ? `tokens in ${p.usage.inputTokens} out ${p.usage.outputTokens}` : "",
        tools.length ? `tools: ${tools.length}` : "",
      ].filter(Boolean).join("\n");
      return {
        content: [{ type: "text", text: `${text}\n\n---\n${footer}` }],
        details: { sessionId: session.sessionId, outcome, tools },
      };
    } finally {
      clearInterval(ticker);
      signal?.removeEventListener("abort", onAbort);
    }
  }

  pi.on("session_start", async (_e, ctx) => {
    uiCtx = ctx;
  });
  for (const ev of ["session_shutdown", "shutdown"]) {
    try {
      pi.on(ev, async () => {
        await client?.then((c) => c.close()).catch(() => undefined);
      });
    } catch {
      /* event not supported by this omp version */
    }
  }

  pi.registerTool({
    name: "muse_code",
    label: "Muse Code",
    description:
      "Delegate a coding or research task in the hackathon workspace to Meta's Muse Code agent (Muse Spark), which runs its own tools (read, search, edit, shell) under the harness approval policy. Reads inside hackathon/ are allowed; writes and shell need allow_writes / allow_shell or a person's approval; anything outside the workspace is denied. Returns Muse's final answer and a session_id to continue the same Muse session. Use for self-contained subtasks, second opinions, or work that should be attributed to Muse.",
    parameters: z.object({
      task: z.string().describe("What Muse should do, with all needed context; Muse does not see this conversation."),
      session_id: z.string().optional().describe("Continue an earlier Muse session (from a previous result)."),
      effort: z.enum(["none", "minimal", "low", "medium", "high", "xhigh", "max", "ultra"]).optional().describe("Muse reasoning effort for this turn."),
      allow_writes: z.boolean().optional().describe("Approve Muse's file writes inside hackathon/ without asking."),
      allow_shell: z.boolean().optional().describe("Approve Muse's shell commands without asking."),
    }),
    async execute(_id, params, signal, onUpdate, ctx) {
      if (ctx) uiCtx = ctx;
      return run(params, signal, onUpdate);
    },
  });

  pi.registerCommand("muse", {
    description: "Ask Muse Code directly: /muse <task>",
    handler: async (args, ctx) => {
      uiCtx = ctx;
      if (!args.trim()) {
        ctx.ui.notify("usage: /muse <task>", "info");
        return;
      }
      ctx.ui.setStatus?.("muse", "muse working…");
      try {
        const r = await run({ task: args.trim() });
        pi.sendMessage({ customType: "muse-code", content: r.content[0]?.text ?? "", display: true }, { triggerTurn: false });
      } catch (e) {
        ctx.ui.notify(`muse failed: ${String(e)}`, "error");
      } finally {
        ctx.ui.setStatus?.("muse", undefined);
      }
    },
  });
}

